import{_ as a,c as t,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1780541309000}'),n={name:"guide/installation.md"};function s(l,e,r,p,d,c){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Gomoku is available for macOS through the Mac App Store. The app costs $4.99 and provides a one-time purchase for full access to all features.</p><h2 id="download-options" tabindex="-1">Download Options <a class="header-anchor" href="#download-options" aria-label="Permalink to &quot;Download Options&quot;">​</a></h2><ul><li><strong>Mac App Store</strong>: <a href="https://apps.apple.com/app/id6771268165" target="_blank" rel="noreferrer">Download Gomoku</a> - $4.99</li></ul><h3 id="mac-app-store-recommended" tabindex="-1">Mac App Store (Recommended) <a class="header-anchor" href="#mac-app-store-recommended" aria-label="Permalink to &quot;Mac App Store (Recommended)&quot;">​</a></h3><p>The Mac App Store version provides automatic updates and seamless integration with macOS.</p><ul><li><strong>Price</strong>: $4.99 (one-time purchase)</li><li><strong>App Store ID</strong>: 6771268165</li><li><strong>Link</strong>: <a href="https://apps.apple.com/app/id6771268165" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6771268165</a></li></ul><h3 id="github-releases-alternative" tabindex="-1">GitHub Releases (Alternative) <a class="header-anchor" href="#github-releases-alternative" aria-label="Permalink to &quot;GitHub Releases (Alternative)&quot;">​</a></h3><p>If you prefer to download directly, you can get the app from GitHub Releases. Note that this version does not receive automatic updates.</p><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h2><h3 id="mac-app-store-installation-recommended" tabindex="-1">Mac App Store Installation (Recommended) <a class="header-anchor" href="#mac-app-store-installation-recommended" aria-label="Permalink to &quot;Mac App Store Installation (Recommended)&quot;">​</a></h3><ol><li>Click the &quot;Download Gomoku&quot; link above or search for &quot;Gomoku&quot; in the Mac App Store</li><li>Click &quot;Get&quot; or &quot;Buy&quot; to purchase the app ($4.99)</li><li>The app will automatically download and install</li><li>Launch Gomoku from your Applications folder or Launchpad</li></ol><h3 id="github-releases-installation" tabindex="-1">GitHub Releases Installation <a class="header-anchor" href="#github-releases-installation" aria-label="Permalink to &quot;GitHub Releases Installation&quot;">​</a></h3><ol><li>Download the latest <code>.dmg</code> from the Releases page</li><li>Double-click the downloaded <code>.dmg</code> to open it</li><li>Drag the <code>Gomoku.app</code> icon into your <code>Applications</code> folder</li><li>Eject the mounted image and open <code>Gomoku</code> from <code>Applications</code></li></ol><p>If macOS prevents opening the app (Gatekeeper), open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong> for Gomoku, or right-click the app and choose <strong>Open</strong>.</p><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><p>When you launch Gomoku for the first time, you may be prompted to grant the following permissions:</p><ul><li><strong>Local Network</strong>: Required for LAN play so other devices on your Wi‑Fi can discover and join games</li><li><strong>Files and Folders</strong>: To save and open game records (SGF) and settings</li><li><strong>Accessibility / Screen Recording</strong>: Optional; only needed if you enable auxiliary features that capture the screen or use overlay helpers</li></ul><p>Grant permissions when prompted. You can modify these permissions at any time in <strong>System Settings → Privacy &amp; Security</strong>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><ul><li><strong>Mac App Store version</strong>: Updates are handled automatically by the App Store</li><li><strong>GitHub Releases version</strong>: Download the newer release and replace the app in <code>Applications</code></li></ul><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>To uninstall Gomoku:</p><ol><li>Quit Gomoku</li><li>Drag <code>Gomoku.app</code> from <code>Applications</code> to the Trash</li><li>(Optional) Remove app data and logs:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.gomoku</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/gomoku</span></span></code></pre></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>macOS</strong>: Monterey (12) or later recommended</li><li><strong>CPU</strong>: Apple Silicon (M-series) or Intel (64-bit)</li><li><strong>Memory</strong>: 4GB minimum, 8GB recommended</li><li><strong>Storage</strong>: ~200 MB (varies by build)</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If you encounter issues during installation:</p><ul><li><strong>macOS blocks the app</strong>: Open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong> for Gomoku</li><li><strong>LAN issues</strong>: Ensure all devices are on the same Wi‑Fi network and that <strong>Local Network</strong> permission was granted</li><li><strong>Notarization warning</strong>: Download a signed/notarized build from the Mac App Store or GitHub Releases</li></ul><p>For more help, visit the <a href="./troubleshooting.html">Troubleshooting guide</a> or open an issue on the project repository.</p>`,31)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
